 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json)
 VALUES('macro-version:'||lower(hex(randomblob(16))),NEW.project_id,NEW.created_at,'data','macro.version_saved','succeeded','user',NEW.created_by,'dashboard','macro',NEW.macro_id,json_object('version',NEW.version));
END;
DROP TRIGGER macro_archive_audit;
CREATE TRIGGER macro_archive_audit AFTER UPDATE OF archived_at ON macro_heads WHEN OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL BEGIN
 INSERT INTO audit_events(id,project_id,at,category,action,outcome,actor_type,actor_id,source,target_type,target_id,detail_json)
 SELECT 'macro-archive:'||lower(hex(randomblob(16))),m.project_id,NEW.archived_at,'data','macro.archived','succeeded',CASE WHEN NEW.archived_by IS NULL THEN 'system' ELSE 'user' END,NEW.archived_by,'dashboard','macro',m.id,json_object('version',NEW.version) FROM macros m JOIN macro_versions v ON v.macro_id=m.id AND v.version=NEW.version WHERE m.id=NEW.macro_id;
END;

-- Every public writer shares the durable journal; the scheduler can recover a
-- process exit after commit without replaying external actions.
-- workflow_event_sequence keeps ids monotonic. No AUTOINCREMENT: SQLite would write
-- sqlite_sequence for every statement whose triggers could journal, fenced or not.
CREATE TABLE workflow_event_sequence(id INTEGER PRIMARY KEY CHECK(id=1),next_id INTEGER NOT NULL);
CREATE TABLE workflow_events(id INTEGER PRIMARY KEY,event_key TEXT UNIQUE,project_id TEXT NOT NULL REFERENCES projects(id),conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,kind TEXT NOT NULL,at INTEGER NOT NULL,source TEXT NOT NULL,revision INTEGER NOT NULL,last_message_id TEXT,ticket_version INTEGER NOT NULL,before_json TEXT NOT NULL DEFAULT '{}',after_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',error TEXT,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at INTEGER,lease_token TEXT,lease_until INTEGER,last_tick TEXT,rules_done INTEGER NOT NULL DEFAULT 0,routing_done INTEGER NOT NULL DEFAULT 0,time_reset_done INTEGER NOT NULL DEFAULT 0,rule_position INTEGER NOT NULL DEFAULT -1,rule_after_id TEXT NOT NULL DEFAULT '');
CREATE TRIGGER workflow_event_sequence_advance AFTER INSERT ON workflow_events BEGIN INSERT INTO workflow_event_sequence(id,next_id) VALUES(1,NEW.id+1) ON CONFLICT(id) DO UPDATE SET next_id=max(next_id,excluded.next_id); END;
CREATE INDEX workflow_events_pending ON workflow_events(state,next_attempt_at,project_id,id);
CREATE INDEX workflow_events_ticket ON workflow_events(project_id,conversation_id,id);
CREATE TABLE workflow_queue_turns(queue TEXT NOT NULL,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,turn INTEGER NOT NULL,PRIMARY KEY(queue,project_id));
CREATE TABLE workflow_clock(project_id TEXT PRIMARY KEY REFERENCES projects(id),now INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE ticket_followups(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),original_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,conversation_id TEXT NOT NULL UNIQUE REFERENCES conversations(id) ON DELETE CASCADE,command_key TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(project_id,original_id,command_key));
CREATE TRIGGER workflow_created AFTER UPDATE OF last_message_id ON conversations WHEN OLD.last_message_id IS NULL AND NEW.last_message_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM contact_erasures e WHERE e.project_id=NEW.project_id AND e.contact_id=NEW.contact_id) BEGIN
 INSERT OR IGNORE INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,after_json) VALUES((SELECT next_id FROM workflow_event_sequence WHERE id=1),'created:'||NEW.id,NEW.project_id,NEW.id,'created',NEW.updated_at,NEW.ticket_source,NEW.revision,NEW.last_message_id,NEW.ticket_version,json_object('status_id',NEW.status_id,'status_category',NEW.status_category,'assigned_to',NEW.assigned_to,'group_id',NEW.group_id,'subject',NEW.subject,'priority',NEW.priority,'channel',NEW.channel,'brand_id',NEW.brand_id,'requester_id',NEW.requester_id,'contact_id',NEW.contact_id,'revision',NEW.revision,'last_message_id',NEW.last_message_id,'ticket_version',NEW.ticket_version,'actor_role',(SELECT actor_role FROM messages WHERE id=NEW.last_message_id)));
END;
CREATE TRIGGER workflow_changed AFTER UPDATE OF revision,status_id,status_category,priority,assigned_to,group_id,subject,channel ON conversations WHEN OLD.last_message_id IS NOT NULL AND NEW.last_message_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.id) AND NOT EXISTS(SELECT 1 FROM contact_erasures e WHERE e.project_id=NEW.project_id AND e.contact_id=NEW.contact_id) AND (NEW.revision<>OLD.revision OR NEW.status_id<>OLD.status_id OR NEW.status_category<>OLD.status_category OR NEW.priority<>OLD.priority OR NEW.assigned_to IS NOT OLD.assigned_to OR NEW.group_id IS NOT OLD.group_id OR NEW.subject<>OLD.subject OR NEW.channel<>OLD.channel) BEGIN
 INSERT OR IGNORE INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) VALUES((SELECT next_id FROM workflow_event_sequence WHERE id=1),CASE WHEN NEW.revision<>OLD.revision THEN 'message:'||NEW.last_message_id ELSE 'changed:'||lower(hex(randomblob(16))) END,NEW.project_id,NEW.id,CASE WHEN NEW.revision<>OLD.revision AND (SELECT actor_role FROM messages WHERE id=NEW.last_message_id)='contact' THEN 'customer_reply' WHEN NEW.revision<>OLD.revision THEN 'operator_reply' ELSE 'changed' END,NEW.updated_at,NEW.ticket_source,NEW.revision,NEW.last_message_id,NEW.ticket_version,json_object('status_id',OLD.status_id,'status_category',OLD.status_category,'assigned_to',OLD.assigned_to,'group_id',OLD.group_id,'subject',OLD.subject,'priority',OLD.priority,'channel',OLD.channel,'brand_id',OLD.brand_id,'requester_id',OLD.requester_id,'contact_id',OLD.contact_id,'revision',OLD.revision,'last_message_id',OLD.last_message_id,'ticket_version',OLD.ticket_version),json_patch(json_object('status_id',NEW.status_id,'status_category',NEW.status_category,'assigned_to',NEW.assigned_to,'group_id',NEW.group_id,'subject',NEW.subject,'priority',NEW.priority,'channel',NEW.channel,'brand_id',NEW.brand_id,'requester_id',NEW.requester_id,'contact_id',NEW.contact_id,'revision',NEW.revision,'last_message_id',NEW.last_message_id,'ticket_version',NEW.ticket_version),json_object('message_id',CASE WHEN NEW.revision<>OLD.revision THEN NEW.last_message_id ELSE NULL END,'actor_role',CASE WHEN NEW.revision<>OLD.revision THEN (SELECT actor_role FROM messages WHERE id=NEW.last_message_id) ELSE NULL END,'is_note',0)));
END;

CREATE TRIGGER workflow_conversation_tags_insert AFTER INSERT ON conversation_tags WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=NEW.conversation_id) BEGIN
 INSERT INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) SELECT (SELECT next_id FROM workflow_event_sequence WHERE id=1),'changed:'||lower(hex(randomblob(16))),c.project_id,c.id,'changed',coalesce((SELECT max(at) FROM ticket_history WHERE conversation_id=c.id),c.updated_at),c.ticket_source,c.revision,c.last_message_id,c.ticket_version,'{}',json_object('status_id',c.status_id,'status_category',c.status_category,'assigned_to',c.assigned_to,'group_id',c.group_id,'subject',c.subject,'priority',c.priority,'channel',c.channel,'brand_id',c.brand_id,'requester_id',c.requester_id,'contact_id',c.contact_id,'revision',c.revision,'last_message_id',c.last_message_id,'ticket_version',c.ticket_version,'tags',json((SELECT json_group_array(tag_id) FROM conversation_tags WHERE conversation_id=c.id)),'fields',json((SELECT json_group_object(field_id,json(value_json)) FROM ticket_field_values WHERE conversation_id=c.id))) FROM conversations c WHERE c.id=NEW.conversation_id AND c.last_message_id IS NOT NULL;
END;

CREATE TRIGGER workflow_conversation_tags_update AFTER UPDATE ON conversation_tags WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=NEW.project_id AND f.conversation_id=NEW.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=NEW.conversation_id) BEGIN
 INSERT INTO workflow_events(id,event_key,project_id,conversation_id,kind,at,source,revision,last_message_id,ticket_version,before_json,after_json) SELECT (SELECT next_id FROM workflow_event_sequence WHERE id=1),'changed:'||lower(hex(randomblob(16))),c.project_id,c.id,'changed',coalesce((SELECT max(at) FROM ticket_history WHERE conversation_id=c.id),c.updated_at),c.ticket_source,c.revision,c.last_message_id,c.ticket_version,'{}',json_object('status_id',c.status_id,'status_category',c.status_category,'assigned_to',c.assigned_to,'group_id',c.group_id,'subject',c.subject,'priority',c.priority,'channel',c.channel,'brand_id',c.brand_id,'requester_id',c.requester_id,'contact_id',c.contact_id,'revision',c.revision,'last_message_id',c.last_message_id,'ticket_version',c.ticket_version,'tags',json((SELECT json_group_array(tag_id) FROM conversation_tags WHERE conversation_id=c.id)),'fields',json((SELECT json_group_object(field_id,json(value_json)) FROM ticket_field_values WHERE conversation_id=c.id))) FROM conversations c WHERE c.id=NEW.conversation_id AND c.last_message_id IS NOT NULL;
END;

CREATE TRIGGER workflow_conversation_tags_delete AFTER DELETE ON conversation_tags WHEN NOT EXISTS(SELECT 1 FROM move_in_native_fences f WHERE f.project_id=OLD.project_id AND f.conversation_id=OLD.conversation_id) AND NOT EXISTS(SELECT 1 FROM conversations c JOIN contact_erasures er ON er.project_id=c.project_id AND er.contact_id=c.contact_id WHERE c.id=OLD.conversation_id) BEGIN
